 return `<div ${id?`id="${esc(id)}"`:''} class="training-diagnostic ${inline?'is-inline ':''}${issue.severity}" data-validation-field="${esc(issue.name)}" tabindex="-1">${inline?'':`<h3>${esc(issueLabel(issue))}</h3>`}<p class="task-field-issue ${issue.severity}">${esc(issue.message)}</p><p class="training-diagnostic-repair"><strong>Suggested repair</strong> ${esc(validationSuggestion(issue))}</p>${values.length?`<dl class="training-diagnostic-values">${values.map(name=>`<dt>${name==='actual'?'Current':'Expected'}</dt><dd><code>${esc(diagnosticValue(issue[name]))}</code></dd>`).join('')}</dl>`:''}${issue.details?`<details><summary>Error details</summary><pre>${esc(diagnosticValue(issue.details))}</pre></details>`:''}${refreshWeight&&canRefreshIssueWeight(issue)?'<button type="button" data-training-action="repair-weight-settings">Restore selected weight settings</button>':''}</div>`;
